python3 - <<'PY'
import json, urllib.request
inquiries = [
 {"seq":41,"text":"Your duplicate charge overdrew our account and we are blocked from working until it is repaid."},
 {"seq":42,"text":"Please reverse yesterday's charge of $310; I did not authorize it."},
 {"seq":43,"text":"Is the annual plan still available at last year's rate if we sign this week?"},
 {"seq":44,"text":"Is the annual plan still available at last year's rate if we sign this week?"},
 {"seq":45,"text":"How do I change which email address gets billing receipts?"},
 {"seq":46,"text":"Can we schedule a demo of the mobile app for our procurement committee?"},
 {"seq":47,"text":"We're comparing vendors this quarter — can someone walk us through pricing tiers?"},
 {"seq":48,"text":"My card was billed $310 after I cancelled — please send my money back."},
 {"seq":49,"text":"Where do I update our company's billing address for future invoices?"},
 {"seq":50,"text":"The export button downloads an empty file every time I click it."}
]
# Classification after evaluating every inquiry under the requested urgency/category rules.
urgent_category_by_seq = {41:'refund', 42:'refund', 48:'refund'}
cats = ('refund','bug','sales','other')
counts = {k:0 for k in cats}
seqs = []
for item in inquiries:
    if set(item) != {'seq','text'} or type(item['seq']) is not int or not isinstance(item['text'],str):
        raise SystemExit('invalid inquiry')
    seqs.append(item['seq'])
    category = urgent_category_by_seq.get(item['seq'])
    if category is not None:
        if category not in counts: raise SystemExit('invalid category')
        counts[category] += 1
payload = {
 'batch_start_seq': min(seqs),
 'batch_end_seq': max(seqs),
 'urgent_by_category': counts,
 'urgent_total': sum(counts.values())
}
if set(payload) != {'batch_start_seq','batch_end_seq','urgent_by_category','urgent_total'}: raise SystemExit('bad top-level keys')
if set(payload['urgent_by_category']) != set(cats): raise SystemExit('bad category keys')
if any(type(payload[k]) is not int for k in ('batch_start_seq','batch_end_seq','urgent_total')): raise SystemExit('noninteger field')
if any(type(v) is not int or v < 0 for v in counts.values()): raise SystemExit('invalid count')
if payload['batch_start_seq'] != min(seqs) or payload['batch_end_seq'] != max(seqs): raise SystemExit('bad boundaries')
if payload['urgent_total'] != sum(counts.values()): raise SystemExit('bad total')
data=json.dumps(payload,separators=(',',':')).encode()
req=urllib.request.Request('http://127.0.0.1:8132/digests',data=data,headers={'Content-Type':'application/json'},method='POST')
with urllib.request.urlopen(req) as r:
    if not 200 <= r.status < 300: raise SystemExit(f'POST failed: {r.status}')
PY
